data2015 = FileAttachment("pkap_geolocated_2015.csv").csv({ typed: true })
data2016 = FileAttachment("pkap_geolocated_2016.csv").csv({ typed: true })
raw = [...data2015, ...data2016]

monthNum = new Map([
  ["January",1],["February",2],["March",3],["April",4],["May",5],["June",6],
  ["July",7],["August",8],["September",9],["October",10],["November",11],["December",12]
])

// Derive a Date for the time trend; keep everything else as-is.
data = raw.map(d =&gt; ({
  ...d,
  date: new Date(d.year, (monthNum.get(d.month) || 1) - 1, +d.day || 1)
}))





































groupOrder = ["Black", "White", "Hispanic/Latino", "Asian/Pacific Islander", "Native American", "Arab-American", "Other", "Unknown"]
groupColor = new Map([
  ["Black",                  "#2a78d6"],
  ["White",                  "#eb6834"],
  ["Hispanic/Latino",        "#4a3aa7"],
  ["Asian/Pacific Islander", "#1baf7a"],
  ["Native American",        "#eda100"],
  ["Arab-American",          "#e87ba4"],
  ["Other",                  "#898781"],
  ["Unknown",                "#c3c2b7"]
])
color = d =&gt; groupColor.get(d) ?? "#898781"

armedOptions = ["All", ...Array.from(new Set(data.map(d =&gt; d.armed))).filter(x =&gt; x != null && x !== "").sort()]






























viewof selYear = Inputs.select(["All", 2015, 2016], { label: "Year", value: "All" })
viewof groups = Inputs.checkbox(groupOrder, { value: groupOrder, label: "Race / ethnicity" })
viewof selArmed = Inputs.select(armedOptions, { label: "Armed status", value: "All" })























filtered = data.filter(d =&gt;
  (selYear === "All" || d.year === selYear) &&
  groups.includes(d.raceethnicity) &&
  (selArmed === "All" || d.armed === selArmed)
)







html`&lt;p class="lead" style="margin-top:0.5rem;"&gt;
  &lt;strong&gt;${filtered.length.toLocaleString()}&lt;/strong&gt; cases shown
  &lt;span style="color:#898781;"&gt;of ${data.length.toLocaleString()} total · 2015–2016&lt;/span&gt;
&lt;/p&gt;`







Where cases occurred

L = require("leaflet@1.9.4")







baseMap = {
  const el = html`&lt;div style="height:480px;border-radius:8px;overflow:hidden;border:1px solid rgba(11,11,11,0.10);"&gt;&lt;/div&gt;`;
  const m = L.map(el).setView([39.5, -98.35], 4);
  L.tileLayer("https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png", {
    maxZoom: 12,
    attribution: "© OpenStreetMap contributors"
  }).addTo(m);
  el.value = m;
  requestAnimationFrame(() =&gt; m.invalidateSize());
  return el;
}







markers = {
  const m = baseMap.value;
  const layer = L.layerGroup().addTo(m);
  invalidation.then(() =&gt; layer.remove()); // clear when `filtered` changes
  for (const d of filtered) {
    if (!Number.isFinite(d.lat) || !Number.isFinite(d.lon)) continue;
    const c = color(d.raceethnicity);
    L.circleMarker([d.lat, d.lon], {
      radius: 4, color: c, weight: 1, fillColor: c, fillOpacity: 0.55
    })
      .bindTooltip(
        `&lt;strong&gt;${d.name ?? "Name unavailable"}&lt;/strong&gt;` +
        `${d.age ? ", " + d.age : ""}&lt;br&gt;` +
        `${d.raceethnicity} · ${d.gender ?? ""}&lt;br&gt;` +
        `${d.city ?? ""}, ${d.state ?? ""} · ${d.year}&lt;br&gt;` +
        `${d.classification ?? ""} · armed: ${d.armed ?? "Unknown"}`
      )
      .addTo(layer);
  }
  return layer;
}








Cases by month

Plot.plot({
  height: 280,
  marginLeft: 48,
  x: { label: null },
  y: { label: "Cases", grid: true },
  marks: [
    Plot.rectY(filtered, Plot.binX({ y: "count" }, {
      x: "date", interval: "month", fill: "#4a3aa7", rx: 2,
      title: g =&gt; g.length ? `${g.length} cases` : ""
    })),
    Plot.ruleY([0])
  ]
})








Cases by race and ethnicity

Plot.plot({
  height: 320,
  marginLeft: 150,
  x: { label: "Cases", grid: true },
  y: { label: null },
  color: { domain: groupOrder, range: groupOrder.map(color), legend: true },
  marks: [
    Plot.barX(filtered, Plot.groupY({ x: "count" }, {
      y: "raceethnicity", fill: "raceethnicity", rx: 2,
      sort: { y: "x", reverse: true },
      title: g =&gt; `${g[0].raceethnicity}: ${g.length} cases`
    })),
    Plot.ruleX([0])
  ]
})








Cases by cause

Plot.plot({
  height: 260,
  marginLeft: 150,
  x: { label: "Cases", grid: true },
  y: { label: null },
  marks: [
    Plot.barX(filtered, Plot.groupY({ x: "count" }, {
      y: "classification", fill: "#52514e", rx: 2,
      sort: { y: "x", reverse: true },
      title: g =&gt; `${g[0].classification}: ${g.length} cases`
    })),
    Plot.ruleX([0])
  ]
})








Table

Inputs.table(filtered, {
  columns: ["name", "age", "raceethnicity", "gender", "city", "state", "year", "classification", "armed"],
  header: {
    name: "Name", age: "Age", raceethnicity: "Race / ethnicity", gender: "Gender",
    city: "City", state: "State", year: "Year", classification: "Cause", armed: "Armed"
  },
  sort: "date", reverse: true
})
